using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class EquipB2HolySword {
 public static object Run(){if(Application.isPlaying)throw new Exception("Stop play first");var a=UnityEngine.Object.FindObjectsByType<Animator>(FindObjectsInactive.Include,FindObjectsSortMode.None).First(t=>t.name.StartsWith("Meshy_AI_lowpoly_paladin")&&t.gameObject.scene.name=="3DBattleScene");var hand=a.GetComponentsInChildren<Transform>(true).First(t=>t.name=="RightHand");if(hand.Find("Holy Sword Grip"))throw new Exception("Sword already equipped");var path=AssetDatabase.FindAssets("t:Model",new[]{"Assets/3DBattle/Boss2"}).Select(AssetDatabase.GUIDToAssetPath).Single();var model=AssetDatabase.LoadAssetAtPath<GameObject>(path);var textures=AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets/3DBattle/Boss2"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();var main=textures.Single(p=>p.EndsWith("texture.png"));const string matPath="Assets/3DBattle/Boss2/B2HolySword.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(matPath);if(mat==null){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.name="B2HolySword";mat.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(main));mat.SetColor("_BaseColor",Color.white);mat.SetFloat("_Metallic",.65f);mat.SetFloat("_Smoothness",.4f);AssetDatabase.CreateAsset(mat,matPath);}
 var grip=new GameObject("Holy Sword Grip");Undo.RegisterCreatedObjectUndo(grip,"Equip B2 holy sword");grip.transform.SetParent(hand,false);grip.transform.localPosition=new Vector3(.0003f,.0009f,.00025f);grip.transform.localRotation=Quaternion.LookRotation(Vector3.right,Vector3.forward);grip.transform.localScale=Vector3.one*.01f;
 var sword=(GameObject)PrefabUtility.InstantiatePrefab(model,grip.transform);Undo.RegisterCreatedObjectUndo(sword,"Equip B2 holy sword");sword.name="B2 Holy Sword";sword.transform.localPosition=new Vector3(0,.75f,0);foreach(var r in sword.GetComponentsInChildren<Renderer>())r.sharedMaterial=mat;EditorUtility.SetDirty(mat);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(a.gameObject.scene);return new{parent=AnimationUtility.CalculateTransformPath(grip.transform,null),material=matPath,bladeLength=1.9f,scale=sword.transform.lossyScale.ToString()};}
}
